import{z as p,x as A,o as r,c as B,q as E,j as l,D as i,d as n,s as o,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"素数筛","description":"","frontmatter":{"title":"素数筛","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sieve.md","filePath":"cs/sieve.md","lastUpdated":1791063341000}'),d={name:"cs/sieve.md"};function m(h,a,u,c,D,f){const t=A("Mermaid");return r(),B("div",null,[a[2]||(a[2]=E('<h1 id="素数筛" tabindex="-1">素数筛 <a class="header-anchor" href="#素数筛" aria-label="Permalink to &quot;素数筛&quot;">​</a></h1><div class="epigraph"><p>埃氏筛用每个素数划掉倍数，$O(n\\log\\log n)$ 列出 $[1,n]$ 的素数；线性筛让每个合数只被最小素因子划一次。</p><footer>—— 据 Eratosthenes（古典）；线性筛见现代数论算法教材；CLRS 第 31 章整理</footer></div><p>上一课<a href="/cs/interior-point">内点法</a>收束连续优化。主干<a href="/cs/miller-rabin">素性</a>测单个 \\(n\\)。缺口是<strong>区间内全体素数</strong>：筛。不重写 Miller–Rabin。后课欧拉函数在筛的数组上填。接<a href="/cs/prime-generation">素数生成</a>只当密码侧单个大素数，本课是小 \\(n\\) 表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>埃氏：从 \\(2\\) 到 \\(\\sqrt n\\)，是素数则划 \\(p^2,p^2+p,\\ldots\\)。时间 \\(\\sum_{p\\le n}n/p=\\Theta(n\\log\\log n)\\)。空间 \\(O(n)\\)。线性筛（Euler）：维护最小素因子，对每个 \\(i\\) 乘尚未超过 \\(minp[i]\\) 的素数，合数只被最小 \\(p\\) 划到，真正 \\(O(n)\\)。</p><p>分段筛：内存放不下 \\([1,n]\\) 时按块筛，空间 \\(O(\\sqrt n+\\text{块})\\)。</p><p>缺口是列表，不是单次素性测试。</p><h3 id="筛不是因式分解" tabindex="-1">筛不是因式分解 <a class="header-anchor" href="#筛不是因式分解" aria-label="Permalink to &quot;筛不是因式分解&quot;">​</a></h3><p>筛给小素数表。分解大 \\(n\\) 是后课 Pollard rho。不要用埃氏筛分解 256 位整数。</p><p><span class="marginnote">CLRS 31 谈数论算法，筛是预备。线性筛同时可积性函数。后课 \\(\\varphi\\)、\\(\\mu\\) 就地筛出。</span></p><p><span class="marginnote">举例：\\(n=30\\) 时只需让 \\(2,3,5\\) 出手划数——\\(7\\) 的话 \\(7^2=49\\gt 30\\)，它划不到任何没被别人划掉的数。这就是「从 \\(2\\) 到 \\(\\sqrt n\\)」的由来：合数必有不超过 \\(\\sqrt n\\) 的素因子。</span></p><p><span class="marginnote">可以把它想象成在一张乘法口诀表上盖章：埃氏筛里每个合数会被它的每个素因子各盖一次章（比如 \\(12\\) 被 \\(2\\) 和 \\(3\\) 各盖一次），而线性筛的规矩是「只许最小素因子盖章」，于是 \\(12\\) 只在 \\(i=6\\)、\\(p=2\\) 这一步被划一次。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>布尔数组或比特压。埃氏或线性。需要 \\(10^7\\) 内表时线性筛顺便 <code>minp</code>。更大 \\(n\\) 分段。</p>',14)),(r(),l(s,null,{default:i(()=>[o(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E4%B8%8A%E9%99%90%20n%22%5D%20--%3E%20ERA%5B%22%E5%9F%83%E6%B0%8F%EF%BC%9A%E7%B4%A0%E6%95%B0%E5%88%92%E5%80%8D%E6%95%B0%22%5D%0A%20%20N%20--%3E%20LIN%5B%22%E7%BA%BF%E6%80%A7%EF%BC%9A%E6%9C%80%E5%B0%8F%E7%B4%A0%E5%9B%A0%E5%AD%90%22%5D%0A%20%20LIN%20--%3E%20TAB%5B%22%E7%B4%A0%E6%95%B0%E8%A1%A8%22%5D%0A%20%20ERA%20--%3E%20TAB%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"偶数可压掉一半。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"每个合数有素因子 \\(\\le\\sqrt n\\)，故埃氏正确。线性筛的不变量：合数 \\(i\\cdot p\\) 在 \\(p=minp[i\\cdot p]\\) 时首次标记。与快速幂无关：这里没有模幂。",-1)),a[6]||(a[6]=e("p",null,[n("线性筛为什么每个合数只划一次？关键是内层循环在 \\(p \\gt minp[i]\\) 时立刻 "),e("code",null,"break"),n("：")],-1)),(r(),l(s,null,{default:i(()=>[o(t,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22i%20%E4%BB%8E%202%20%E5%88%B0%20n%20%E4%BE%9D%E6%AC%A1%E6%89%AB%E6%8F%8F%22%5D%20--%3E%20B%7B%22i%20%E6%98%AF%E7%B4%A0%E6%95%B0%EF%BC%9F%22%7D%0A%20%20B%20--%20%E6%98%AF%20--%3E%20C%5B%22%E6%8A%8A%20i%20%E8%AE%B0%E5%85%A5%E7%B4%A0%E6%95%B0%E8%A1%A8%22%5D%0A%20%20B%20--%20%E5%90%A6%20--%3E%20D%5B%22minp%5Bi%5D%20%E5%B7%B2%E5%9C%A8%E6%9B%B4%E6%97%A9%E4%B8%80%E6%AD%A5%E5%A1%AB%E5%A5%BD%22%5D%0A%20%20C%20--%3E%20E%5B%22%E9%81%8D%E5%8E%86%E7%B4%A0%E6%95%B0%20p%EF%BC%9A%E6%A0%87%E8%AE%B0%20i*p%22%5D%0A%20%20D%20--%3E%20E%0A%20%20E%20--%3E%20F%7B%22p%20%E6%98%AF%E5%90%A6%E8%B6%85%E8%BF%87%20minp%5Bi%5D%EF%BC%9F%22%7D%0A%20%20F%20--%20%E5%90%A6%20--%3E%20E%0A%20%20F%20--%20%E6%98%AF%20--%3E%20G%5B%22%E7%AB%8B%E5%8D%B3%20break%EF%BC%9A%E7%95%99%E7%BB%99%E6%9B%B4%E5%A4%A7%20i%20%E5%8E%BB%E5%88%92%22%5D%0A"})]),fallback:i(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p>初学者容易以为线性筛只是「埃氏筛写得更好」，实际上它是把「谁有资格划掉某个合数」这件事定成了唯一规则——最小素因子。这条 break 正是 \\(O(n)\\) 的来源：若不 break，\\(i=12\\) 会用 \\(3\\) 划掉 \\(36\\)，而 \\(36\\) 本该由 \\(i=18\\)、\\(p=2\\) 来划。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Atkin 筛细节。不写素数定理证明。后课默认：\\(n\\le 10^7\\) 级用线性筛表。下一课欧拉函数与莫比乌斯。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>埃氏 \\(O(n\\log\\log n)\\)；线性筛 \\(O(n)\\)。</li><li>输出 \\([1,n]\\) 素数，不是大数分解。</li><li>分段筛换空间。</li><li>出处：古典埃氏筛；CLRS 第 31 章。</li></ul>',5))])}const F=p(d,[["render",m]]);export{_ as __pageData,F as default};
